"""Whole-file lessons authored against Linux v6.12, including public headers.

These are individual source-based lessons, not inventory-derived placeholders.
"""
ROWS = []


def add(path, title, intro, principle, use, sections, questions):
    ROWS.append(dict(path=path, title=title, intro=intro, principle=principle,
                     use=use, sections=sections, questions=questions))


COMMON = ('CRC는 비트열을 GF(2) 다항식으로 보고 나머지를 갱신하는 오류 검출 방식입니다. '
          '이 체계에서 덧셈과 뺄셈은 XOR이며 자리올림이 없습니다. CRC는 암호학적 인증 코드가 아니므로 '
          '악의적인 변경을 방지하려면 별도의 인증 설계가 필요합니다. 초기값·비트 방향·마지막 XOR·전송 표현이 '
          '달라지면 같은 입력의 최종 값도 달라집니다.')

add('lib/crc4.c', 'CRC4 전체 구현: 4비트 표와 시프트의 경계',
    '64비트 정수의 일부 비트에서 4비트 체크값을 구하는 작은 함수입니다. 표를 사용하는 최적화와 C 시프트의 정의 범위를 함께 배웁니다.',
    'crc4_tab은 다항식 0b10111에 대한 16가지 4비트 전이입니다. x를 (1ull << bits)-1로 가린 뒤 bits를 4의 배수로 올림합니다. 높은 nibble부터 c XOR nibble을 인덱스로 사용해 상태를 갱신합니다.',
    'c는 0..15 범위의 유효한 CRC 상태여야 합니다. 이 구현의 마스크 식 때문에 bits는 0..63 범위에서 해석해야 합니다. bits=64를 지원한다고 추측하면 안 됩니다. 결과를 다음 호출의 초기 상태로 쓸 때는 nibble 패딩 규칙도 맞춰야 합니다.',
    [('전체 파일 구성', 'SPDX와 주석은 파일의 메타데이터입니다. crc4.h는 함수 선언과 형식, module.h는 export 및 모듈 메타데이터 매크로를 제공합니다. static const crc4_tab은 이 번역 단위 내부의 읽기 전용 전이 표입니다. 함수 뒤의 EXPORT_SYMBOL_GPL은 커널 심볼 공개이고 사용자 공간 syscall을 만드는 구문이 아닙니다. MODULE_DESCRIPTION과 MODULE_LICENSE는 연산 단계가 아닙니다.'),
     ('실행 순서와 경계', 'bits=5이면 낮은 5비트만 남기고 루프 길이를 8로 만듭니다. 따라서 상위 nibble에는 0으로 채워진 비트가 포함됩니다. bits=0이면 x=0이고 i=-4로 시작해 루프가 없습니다. c가 그대로 반환됩니다. bits=64이면 64비트 값의 폭만큼 왼쪽 시프트하므로 C에서 정의되지 않은 동작입니다. 함수 안에 입력 검증이나 오류 반환 경로는 없습니다.'),
     ('손으로 계산하기', 'c=0, x=0xAB, bits=8이면 첫 인덱스는 0 XOR 0xA=0xA이고 표 값은 0xF입니다. 다음 인덱스는 0xF XOR 0xB=4이고 결과는 0xB입니다. x=0xAB, bits=5면 먼저 x=0xB가 되고 두 nibble 0,0xB를 처리하여 결과 0x8입니다.'),
     ('CS 연결과 비용', COMMON+' 입력 bits에 대해 ceil(bits/4)번 표를 조회합니다. 이 API는 bits가 최대 63인 고정 폭이므로 유효 입력의 반복 횟수는 최대 16회입니다. 임의 길이 입력의 점근적 분석과 고정 폭 API의 상한을 구분하세요.')],
    [('c=0, x=0xAB, bits=8의 결과는?', '0xB', '0x8', '첫 상태는 tab[0xA]=0xF, 두 번째 상태는 tab[0xF XOR 0xB]=tab[4]=0xB입니다. 0x8은 bits=5로 마스크한 다른 입력의 결과입니다.'),
     ('bits=5를 8로 올린다는 것은 원래 상위 비트를 되살린다는 뜻인가?', '아니다. 먼저 5비트 마스크를 적용한 뒤 0 패딩된 nibble을 처리한다', '그렇다. x의 원래 상위 3비트도 포함한다', '마스크 대입이 올림보다 먼저 실행됩니다. 제거된 상위 비트는 복구되지 않고 올림은 반복문의 경계만 바꿉니다.'),
     ('bits=64에 대한 이 구현의 문제는?', '1ull을 형식 폭만큼 시프트하여 정의되지 않은 동작이 된다', '자동으로 모든 비트가 1인 마스크가 된다', 'C의 시프트 수는 승격된 왼쪽 피연산자의 비트 폭보다 작아야 합니다. 수학적 2^64-1 계산과 실제 C 표현식은 다릅니다.'),
     ('초기 c=0x80을 넘겨도 함수가 4비트로 자동 제한하는가?', '아니다. 표 인덱스가 범위를 벗어날 수 있다', '그렇다. 반환 형식 uint8_t가 입력을 4비트로 만든다', 'c 자체에 &0xf를 하지 않습니다. uint8_t는 8비트이므로 0x80을 유지하며 nibble과 XOR해도 16칸 표의 유효 인덱스가 되지 않습니다.')])

add('include/linux/crc4.h', 'CRC4 헤더 전체: 선언과 실행 계약의 차이',
    '짧은 헤더라도 중복 포함 방지, 정수 폭, 외부 함수 선언과 입력 계약을 읽어야 합니다.',
    '_LINUX_CRC4_H 가드는 같은 번역 단위의 중복 포함을 막습니다. linux/types.h를 포함한 뒤 uint8_t crc4(uint8_t c, uint64_t x, int bits)를 외부 함수로 선언합니다. 구현과 표는 lib/crc4.c에 있습니다.',
    '호출자는 uint64_t 입력이라고 해서 bits=64가 안전하다고 단정하면 안 됩니다. 선언은 매개변수의 형식을 설명하고, 실제 값의 범위와 패딩 동작은 구현을 함께 읽어 확인합니다.',
    [('전체 선언과 링크', 'SPDX 표기는 메타데이터이고 #ifndef/#define/#endif가 헤더 전체를 감쌉니다. linux/types.h가 고정 폭 형식을 제공합니다. extern 함수 선언은 다른 파일에 있는 구현을 참조할 수 있게 하지만 기계어 본문을 만들지는 않습니다. 구현이 링크되어야 호출을 해결할 수 있습니다.'),
     ('형식과 값 범위', 'c와 반환값은 8비트 형식이지만 의미상 CRC4 상태는 4비트입니다. x의 64비트 폭과 bits 인자의 허용 범위는 다른 개념입니다. bits는 signed int라 음수도 형식상 전달되지만 올바른 호출 계약이 아닙니다. lib/crc4.c의 시프트·표 인덱스를 보고 0<=bits<64, 0<=c<16 전제를 확인합니다.'),
     ('CS 연결', '정적 형식 검사는 모든 의미 제약을 표현하지 못합니다. 타입이 맞는 호출도 값 범위 계약을 어길 수 있습니다. 공개 API를 읽을 때 선언, 구현, 호출자를 함께 확인하는 이유입니다.')],
    [('이 헤더만 포함하면 crc4의 함수 본문도 생기는가?', '아니다. 외부 선언이며 구현 링크가 필요하다', '그렇다. extern이 본문을 자동 생성한다', '헤더에는 세미콜론으로 끝나는 함수 원형만 있습니다. 링크 단계에서 lib/crc4.c의 정의를 연결해야 합니다.'),
     ('uint8_t 반환형이 의미하는 것은?', '8비트 값을 반환하며 의미상 유효 CRC4 값의 조건은 별도다', '모든 uint8_t 값이 유효한 4비트 CRC 초기값이다', '자료형의 256가지 값과 CRC4 상태의 16가지 값은 다릅니다. 구현은 초기 c를 마스크하지 않으므로 호출 계약을 따라야 합니다.')])

add('lib/crc7.c', 'CRC7 전체 구현: 왼쪽 정렬 상태와 256칸 전이 표',
    '7비트 CRC를 바이트의 상위 7비트에 넣는 구현입니다. 수학적 값과 저장 표현을 구분합니다.',
    'crc7_be_syndrome_table은 x^7+x^3+1에 대한 바이트 전이 표입니다. 각 결과는 왼쪽 정렬되어 최하위 비트가 0입니다. crc7_be는 len개 바이트를 차례로 crc7_be_byte에 전달하고 마지막 상태를 반환합니다.',
    '초기 crc와 결과는 왼쪽 정렬 표현으로 다룹니다. 함수는 초기화값이나 프로토콜의 마지막 stop bit를 자동 삽입하지 않습니다. len이 0이면 초기값을 그대로 반환합니다.',
    [('전체 파일 구성', 'types.h는 u8와 size_t 등의 형식, crc7.h는 한 바이트 helper와 공개 선언, module.h는 export 및 메타데이터를 제공합니다. 파일의 핵심 정의는 256개 u8 상수와 crc7_be 함수이며 두 심볼을 EXPORT_SYMBOL로 공개합니다. MODULE_DESCRIPTION/LICENSE는 계산에 참여하지 않습니다.'),
     ('전이 표와 표현', '표의 모든 원소가 짝수인 것은 7비트 나머지를 한 비트 왼쪽으로 정렬했기 때문입니다. crc7_be_byte의 인덱스는 crc XOR data입니다. 값 0x12는 저장 표현이고 정렬을 제거한 7비트 값은 0x09입니다. CPU 메모리의 리틀/빅 엔디언과 CRC의 비트 처리 방향을 동일시하지 않습니다.'),
     ('루프와 수명', 'while(len--)는 바이트 하나마다 buffer를 증가시킵니다. len=0이면 버퍼를 읽지 않으며 crc를 반환합니다. 양수 len에는 그 길이의 읽을 수 있는 버퍼가 필요합니다. 표가 const이고 지역 상태만 변경하므로 유효한 읽기 버퍼를 공유하는 호출 간에 CRC 상태를 서로 덮어쓰지 않습니다.'),
     ('숫자 예시와 비용', '초기값 0에 바이트 0x01을 넣으면 tab[1]=0x12입니다. 다음 바이트도 0x01이면 인덱스 0x13이고 tab[0x13]=0x04입니다. n바이트에 O(n) 시간, 상태 O(1), 공유 표 256바이트를 사용합니다. '+COMMON)],
    [('초기 0에서 [0x01,0x01]을 처리한 저장 CRC는?', '0x04', '0x12', '첫 바이트 후 0x12, 두 번째 인덱스는 0x12 XOR 1=0x13이고 tab[19]=0x04입니다. 0x12는 첫 바이트만 처리한 값입니다.'),
     ('저장 결과의 최하위 비트가 0인 이유는?', '7비트 CRC를 바이트의 상위 7비트에 정렬하기 때문', '입력 데이터의 최하위 비트를 모두 버리기 때문', '입력은 표 인덱스에 전부 반영됩니다. 0인 비트는 출력 상태 표현의 남는 한 자리이지 무시한 입력 비트를 뜻하지 않습니다.'),
     ('crc7_be가 프로토콜의 마지막 stop bit까지 붙이는가?', '아니다. 호출자가 전송 형식을 완성해야 한다', '그렇다. 결과의 최하위 비트가 항상 1이다', '함수의 결과는 최하위 비트가 0인 왼쪽 정렬 상태입니다. 별도의 전송 비트를 덧붙이는 로직은 이 파일에 없습니다.')])

add('include/linux/crc7.h', 'CRC7 헤더 전체: inline 바이트 갱신과 외부 표',
    '인라인 helper가 실행되는 계산과 외부 객체의 저장 위치를 구별합니다.',
    'crc7_be_syndrome_table[256]을 extern const u8로 선언하고 crc7_be_byte는 table[crc XOR data]를 반환합니다. crc7_be는 버퍼 처리 함수의 외부 선언입니다.',
    'crc와 data가 u8라 XOR 결과는 0..255여서 표 인덱스에 맞습니다. 이는 상태가 올바른 왼쪽 정렬 CRC인지는 보장하지 않으므로 표현 계약은 호출자가 지켜야 합니다.',
    [('파일 전체', 'SPDX와 _LINUX_CRC7_H 헤더 가드, linux/types.h 포함, 외부 상수 표 선언, static inline helper 정의, 외부 버퍼 함수 선언 순서입니다. helper의 static은 번역 단위 내부 연결이고 inline은 최적화 가능성을 나타내며 외부 표의 정의를 대신하지 않습니다.'),
     ('한 바이트 계산', 'crc=0x12, data=0x01이면 인덱스는 0x13입니다. lib/crc7.c의 해당 표 원소가 0x04이므로 결과는 0x04입니다. 포인터를 받거나 버퍼를 순회하지 않아 한 번 호출은 한 바이트만 갱신합니다.'),
     ('CS 연결', '배열 인덱스의 수치적 안전성과 자료 표현의 의미적 타당성은 별개입니다. 모든 u8 XOR 인덱스는 표 범위 안이지만 홀수 초기 상태는 일반적인 왼쪽 정렬 CRC7 계약에 맞지 않습니다.')],
    [('crc7_be_byte 한 번은 몇 바이트를 처리하는가?', '1바이트', 'len만큼의 전체 버퍼', '인자로 u8 data 하나만 받습니다. 전체 버퍼 루프는 crc7_be에 있습니다.'),
     ('헤더의 extern const 표 선언은 매 포함마다 새 256바이트 표를 정의하는가?', '아니다. 외부 표의 존재와 형식을 선언한다', '그렇다. 모든 호출마다 표를 복사한다', '이 선언에는 초기화 데이터가 없으며 실제 정의는 lib/crc7.c에 있습니다. helper는 그 표를 읽을 뿐 복사하지 않습니다.')])

add('lib/crc8.c', 'CRC8 전체 구현: GF(2)의 선형성과 표 생성',
    '고정 표가 아니라 다항식과 비트 방향에 맞는 표를 먼저 생성합니다. 표 생성과 메시지 처리는 서로 다른 단계입니다.',
    'crc8_populate_msb는 i=1,2,...128로 기존 구간을 두 배씩 채웁니다. t를 왼쪽 이동하고 이전 최상위 비트에 따라 polynomial을 XOR합니다. crc8_populate_lsb는 i=128,64,...1로 내려가며 오른쪽 이동과 최하위 비트 기준 XOR로 표를 채웁니다. crc8은 table[(crc XOR byte)&0xff]로 데이터 상태를 갱신합니다.',
    '표는 256바이트 공간을 제공하고 사용 전에 알맞은 다항식으로 초기화해야 합니다. 메시지 처리 중 다른 실행 흐름이 표를 다시 만들면 안 됩니다. 초기값과 최종 보수 처리는 호출자의 프로토콜 계약입니다.',
    [('파일 전체 구성', '상단 저작권·허용문은 원본 메타데이터로 보존합니다. pr_fmt 정의와 printk.h 포함은 출력 형식 기반을 제공하지만 이 파일의 세 함수 안에는 로그 출력이 없습니다. crc8.h가 크기와 선언을, module.h가 export와 모듈 정보를 제공합니다. 세 함수가 모두 EXPORT_SYMBOL 대상입니다.'),
     ('MSB 표 생성의 불변식', '처음 table[0]=0입니다. i 단계 직전 table[0..i-1]가 완성되어 있고 안쪽 루프가 table[i+j]=table[j] XOR t로 다음 구간을 채웁니다. t는 새 비트에 해당하는 기저 전이입니다. GF(2)의 선형성 때문에 비트 조합의 전이를 XOR로 만들 수 있습니다. 전체 추가 대입은 1+2+4+...+128=255회입니다.'),
     ('LSB 표 생성의 순서', '첫 단계 i=128에서 table[128]을 만들고 다음 i=64에서 table[64],table[192]를 만듭니다. j는 2*i씩 증가하므로 읽는 table[j]는 이전 단계에 준비된 조합입니다. 방향이 반대인 다항식 비트 표현도 함께 맞춰야 하며 MSB 다항식 값을 그대로 LSB 함수에 넘기면 일반적으로 다른 CRC가 됩니다.'),
     ('버퍼 처리와 경계', 'crc8은 표를 생성하지 않고 nbytes만큼 읽습니다. nbytes=0이면 초기 crc를 그대로 돌려줍니다. crc와 입력이 u8이므로 XOR는 0..255이고 &0xff가 인덱스 폭을 명시합니다. 반환형 u8에 저장될 때 상위 비트가 잘리며 표 생성의 t 갱신도 이 폭을 이용합니다. 동적 할당·오류 코드·최종 보수는 없습니다.'),
     ('계산과 복잡도', 'MSB polynomial=0x07이면 table[0]=0, table[1]=7, table[2]=14, table[3]=9입니다. 초기 crc=0에 [1,2]를 처리하면 첫 상태 7, 다음 인덱스 5, table[5]=0x1B입니다. 두 표 생성은 256칸을 채우는 고정 비용이고 메시지 n바이트의 시간은 O(n), 추가 상태 O(1)입니다. '+COMMON)],
    [('MSB 표 생성에서 table[i+j]=table[j] XOR t가 가능한 근거는?', 'GF(2) 전이의 선형성을 사용한다', '일반 정수 덧셈의 자리올림을 사용한다', '다항식 계수는 0과 1이고 합은 XOR입니다. 기존 조합에 새 비트의 전이를 XOR해 결합하므로 산술 자리올림은 필요하지 않습니다.'),
     ('crc8()을 호출하면 전달한 빈 표를 자동으로 초기화하는가?', '아니다. populate를 먼저 호출해야 한다', '그렇다. 첫 바이트에서 다항식을 추론한다', 'crc8의 본문에는 표 대입이나 다항식 인자가 없습니다. 읽기 전에 별도 populate 함수로 완성해야 합니다.'),
     ('MSB polynomial=7, 초기 0, 입력 [1,2]의 결과는?', '0x1B', '0x09', '첫 조회 tab[1]=7, 두 번째 조회 tab[7 XOR 2]=tab[5]=0x1B입니다. tab[3]=9를 쓰는 것은 이전 상태 갱신을 누락한 계산입니다.'),
     ('메시지를 계산하는 동안 다른 스레드가 같은 표를 다시 생성해도 안전한가?', '아니다. 초기화 완료 후 변경하지 않거나 적절히 동기화해야 한다', '그렇다. const 매개변수가 다른 별칭의 쓰기도 막는다', 'const는 해당 포인터를 통한 쓰기를 제한할 뿐 다른 별칭의 변경을 막는 잠금이 아닙니다. 혼합된 다항식 전이 표를 읽으면 결과도 올바르지 않습니다.')])

add('include/linux/crc8.h', 'CRC8 헤더 전체: 초기값·전송 보수·검증 잔여값',
    '체크값을 계산하는 것과 메시지 뒤에 붙여 전송·검증하는 계약을 연결합니다.',
    'CRC8_INIT_VALUE는 0xFF, CRC8_TABLE_SIZE는 256, DECLARE_CRC8_TABLE은 static u8 배열 선언입니다. CRC8_GOOD_VALUE(table)은 table[0xFF]입니다. 두 populate 함수와 crc8의 선언·주석이 비트 방향과 분할 버퍼 처리 계약을 설명합니다.',
    '헤더의 사용법은 마지막 CRC를 보수로 바꿔 전송하는 경우를 설명합니다. 수신측은 CRC 바이트까지 포함해 계산한 잔여값을 GOOD_VALUE와 비교합니다. 단순히 항상 0과 비교하는 규칙이 아닙니다.',
    [('메타데이터·가드·형식', '원본 허용문을 보존하고 __CRC8_H_가 중복 포함을 막습니다. linux/types.h 이후 네 매크로와 세 함수 선언이 위치합니다. DECLARE_CRC8_TABLE은 표 크기와 static 저장을 정하지만 원하는 다항식의 표를 완성하지 않습니다.'),
     ('같은 다항식의 두 표현', '문서 예시 x^8+x^7+x^6+x^4+x^2+1은 MSB 우선 표시에 0xD5, LSB 우선 표시에 0xAB를 사용합니다. 최상위 차수 항은 암묵적이며 비트 방향에 따라 나머지 계수의 배치가 달라집니다. 두 함수의 regular/reverse라는 주석 표현만 암기하지 말고 실제 시프트 방향과 함께 읽습니다.'),
     ('불연속 버퍼와 잔여값', 'A를 처리한 상태를 B 처리의 초기값으로 전달하면 A||B를 이어 처리할 수 있습니다. 보수는 매 조각마다 하지 않고 마지막 전송 단계에서 합니다. 마지막 상태가 r이면 전송 바이트는 r XOR 0xff이고, 그 바이트를 처리한 인덱스는 r XOR (r XOR 0xff)=0xff입니다. 따라서 최종 잔여값이 table[0xff]가 됩니다.'),
     ('CS 연결과 한계', COMMON+' 좋은 잔여값은 사용한 다항식 표와 전송 보수 규약에 의존합니다. 표는 읽는 동안 안정적이어야 하며 nbytes의 유효 범위와 버퍼 수명은 호출자가 보장합니다.')],
    [('보수 CRC를 붙인 전체 메시지 검증에서 기대하는 잔여값은?', '사용한 table[0xff]', '모든 표에서 항상 0', '상태 r에 보수 r XOR 0xff를 입력하면 XOR 인덱스가 0xff가 됩니다. 그러므로 마지막 상태는 그 표의 0xff 원소이며 일반적으로 0이 아닙니다.'),
     ('DECLARE_CRC8_TABLE만 실행하면 다항식에 맞는 표가 완성되는가?', '아니다. 256칸 저장소를 선언하고 populate는 별도로 해야 한다', '그렇다. 매크로가 입력 프로토콜을 분석한다', '매크로 본문은 static u8 이름[CRC8_TABLE_SIZE]입니다. 다항식 인자와 표 생성 코드가 없어 원하는 전이를 자동 계산할 수 없습니다.'),
     ('A와 B를 나누어 계산할 때 A의 결과에 보수를 취해 B의 초기값으로 주는가?', '아니다. 중간 상태를 그대로 넘기고 전송 직전에 최종 보수한다', '그렇다. 모든 조각마다 보수해야 한다', '중간 보수는 누적 상태를 변경해 A||B를 연속 처리한 결과와 다르게 만듭니다. 헤더는 이전 반환값을 다음 초기값으로 전달하도록 설명합니다.')])

add('lib/crc16.c', 'CRC16 전체 구현: 0x8005 다항식과 반사 전이 표',
    '16비트라는 이름만 같아도 CRC 알고리즘이 같지는 않습니다. 이 파일은 0x8005 다항식의 반사 방향 전이를 사용합니다.',
    'crc16_table은 256개 u16 원소로 512바이트입니다. 공개 함수 crc16은 buffer를 한 바이트씩 읽고 헤더의 crc16_byte로 갱신합니다. helper는 crc의 하위 바이트와 입력을 XOR해 표를 조회하고 crc>>8과 XOR합니다.',
    '초기 상태는 호출자가 전달합니다. 헤더 설명의 Init 0은 기본 알고리즘 설명이며 함수가 매 호출마다 0으로 덮어쓰지 않습니다. 이전 반환값을 넘겨 조각별 갱신을 이어갈 수 있습니다.',
    [('전체 파일과 공유 표', 'SPDX·설명 주석, types/module/crc16 헤더 포함, 상수 표 정의, 표 export, crc16 함수, 함수 export, 모듈 설명·라이선스가 전부입니다. 표는 읽기 전용 전이 데이터이고 동적 초기화나 메모리 할당은 없습니다.'),
     ('다항식과 비트 방향', '정방향 표기 0x8005를 반사한 비트 처리에는 0xA001을 사용합니다. 표의 각 원소는 입력 인덱스에 대해 하위 비트부터 8번 (r>>1) XOR 조건부 0xA001 전이를 한 값입니다. 모든 256개 원소를 이 독립 비트 루프로 비교할 수 있습니다.'),
     ('계산 예제와 경계', '초기 crc=0, 입력 1이면 tab[1]=0xC0C1입니다. 다음 입력 0이면 crc>>8=0xC0, 인덱스=0xC1, tab[0xC1]=0x90C1, 결과=0x9001입니다. len=0이면 초기값 그대로이며 양수 len에는 유효한 읽기 버퍼가 필요합니다.'),
     ('CS 연결', 'n바이트를 O(n) 시간과 O(1) 지역 상태로 순회합니다. 표 방식은 비트별 8회 전이를 메모리 조회로 바꾸는 시간·공간 절충입니다. '+COMMON)],
    [('초기 0에서 입력 [1,0]의 결과는?', '0x9001', '0xC0C1', '첫 바이트는 0xC0C1이고 두 번째는 0x00C0 XOR tab[0xC1]=0x9001입니다. 0xC0C1은 한 바이트만 처리한 값입니다.'),
     ('crc16 함수가 초기 상태를 매번 0으로 설정하는가?', '아니다. 인자로 받은 상태를 누적한다', '그렇다. 헤더에 Init 0이라고 쓰여 있다', '본문은 전달받은 crc를 그대로 반복 갱신합니다. 기본 초기값과 이어 처리할 때의 이전 상태 전달을 구별해야 합니다.'),
     ('crc16_table의 원소 데이터 크기는?', '256 × 2 = 512바이트', '256바이트', 'u16은 16비트, 즉 2바이트입니다. 256개 원소의 데이터 크기는 512바이트이며 심볼·모듈 전체 크기와는 별개입니다.')])

add('include/linux/crc16.h', 'CRC16 헤더 전체: 하위 바이트 제거와 XOR 갱신',
    '한 줄짜리 갱신식에서 이전 상태와 새 입력이 어떻게 합쳐지는지 추적합니다.',
    'crc16_byte는 (crc>>8) XOR crc16_table[(crc XOR data)&0xff]를 반환합니다. 하위 8비트와 새 바이트를 섞어 표 전이를 선택하고 이전 상위 8비트는 오른쪽으로 내려 결합합니다.',
    '한 바이트 helper와 전체 버퍼 crc16의 역할을 나눠 사용합니다. 외부 표는 lib/crc16.c에서 정의하며 헤더 가드는 중복 선언 방지이지 실행 중 잠금이 아닙니다.',
    [('전체 파일', 'SPDX와 CRC 폭·다항식·기본 초기값 설명, __CRC16_H 가드, types.h 포함, 표와 버퍼 함수의 extern 선언, static inline crc16_byte 정의, 닫는 가드가 전체 내용입니다.'),
     ('형식 승격과 마스크', 'crc와 data는 정수 승격된 뒤 XOR할 수 있으므로 &0xff가 표 인덱스를 정확히 낮은 8비트로 제한합니다. 예를 들어 crc=0x1234,data=0x34이면 인덱스 0, 표 값 0, crc>>8=0x12이므로 결과는 0x0012입니다.'),
     ('CS 연결', '반사 방향 처리에서 낮은 바이트를 먼저 소비합니다. 오른쪽 이동은 정수 연산의 방향이며 메모리에서 u16을 저장하는 엔디언과는 별개의 규칙입니다. helper는 입력 버퍼를 읽거나 포인터를 이동하지 않습니다.')],
    [('crc=0x1234,data=0x34이면 crc16_byte의 결과는?', '0x0012', '0x1200', '낮은 바이트 0x34와 data가 상쇄되어 tab[0]=0입니다. 남는 상태는 crc>>8=0x12입니다.'),
     ('표 인덱스에 &0xff가 필요한 이유는?', '하위 8비트만 사용해 256칸 범위로 제한하려고', '16비트 결과를 항상 0으로 만들려고', 'crc XOR data에는 상위 crc 비트도 남을 수 있습니다. 0xff 마스크가 없으면 그 전체를 256개 표의 인덱스로 사용하게 됩니다.')])

add('lib/crc-ccitt.c', 'CRC-CCITT 전체 구현: 0x8408 반사 전이',
    '같은 차수의 CRC16 파일들과 실제 전이 다항식 및 처리 방향을 비교합니다.',
    'crc_ccitt_table의 각 원소는 반사 다항식 0x8408로 8비트를 처리한 값입니다. crc_ccitt는 바이트마다 crc_ccitt_byte를 호출합니다. 같은 x^16+x^12+x^5+1 계열이어도 ITU-T 파일의 MSB 갱신과 표현이 다릅니다.',
    '초기값·최종 보수와 전송 순서는 호출자가 정합니다. 함수 이름만 보고 특정 통신 규격의 완성된 FCS라고 가정하지 말고 프로토콜 파라미터 전체를 맞추세요.',
    [('전체 파일 구성', 'SPDX와 파일 설명, types/module/crc-ccitt 헤더, 표 생성 원리를 적은 주석, 256개 u16 상수, 표 export, 버퍼 함수와 export, 모듈 메타데이터로 구성됩니다. 표·함수 이외의 동적 상태는 없습니다.'),
     ('표 생성 근거', '각 인덱스 r을 초기값으로 놓고 8번 r=(r>>1) XOR (이전 최하위 비트가 1이면 0x8408)을 계산합니다. 표의 128번 원소가 0x8408인 것도 이 전이와 일치합니다. 일반 덧셈이나 비밀키가 들어가지 않습니다.'),
     ('손 계산과 분할 처리', '초기 0에 바이트 1을 넣으면 표의 1번 값 0x1189입니다. 다음 입력이 0x89이면 인덱스가 0이어서 결과는 0x0011입니다. [1]과 [0x89]를 나누되 이전 상태를 넘겨도 같은 결과를 얻습니다. len=0이면 초기 상태가 그대로입니다.'),
     ('CS 연결', '표는 512바이트, n바이트 처리는 O(n), 추가 상태는 O(1)입니다. '+COMMON)],
    [('초기 0에서 [1,0x89]를 처리한 결과는?', '0x0011', '0x1189', '첫 상태 0x1189에서 낮은 바이트와 두 번째 입력 0x89가 XOR로 사라집니다. 표 0번은 0이고 상위 바이트를 내려 0x11이 됩니다.'),
     ('crc16.c의 표와 이 표를 크기가 같다는 이유로 바꿔도 되는가?', '아니다. 다항식 전이가 다르다', '그렇다. 둘 다 256칸 u16이다', '자료구조의 형식이 같아도 값의 의미가 다릅니다. CRC16의 반사 전이 0xA001과 이 파일의 0x8408은 일반적으로 다른 체크값을 냅니다.'),
     ('계산에 별도 동적 메모리 할당이 있는가?', '없다. 상수 표와 지역 상태를 사용한다', '바이트마다 새 버퍼를 할당한다', '본문은 입력 포인터 증가와 지역 crc 갱신뿐입니다. 입력 버퍼의 소유권이나 수명 관리는 호출자에게 있습니다.')])

add('include/linux/crc-ccitt.h', 'CRC-CCITT 헤더 전체: 상태 소비 방향을 읽는 법',
    '유사한 API를 이름이 아니라 식과 외부 표의 의미로 구별합니다.',
    '외부 표와 crc_ccitt 선언을 제공하고 inline crc_ccitt_byte는 (crc>>8) XOR table[(crc XOR c)&0xff]를 수행합니다. 반사 방향 바이트 전이는 표 정의와 함께 결정됩니다.',
    'crc16_byte와 식 모양은 같지만 참조하는 표가 다릅니다. 값 계산을 검토할 때 helper의 수식뿐 아니라 테이블 정의까지 따라가야 합니다.',
    [('파일 전체 구조', 'SPDX, _LINUX_CRC_CCITT_H 가드, types.h, 외부 u16 표, 버퍼 함수 선언, static inline helper, #endif가 전체입니다. 헤더에는 표 초기화나 버퍼 루프가 없습니다.'),
     ('직접 추적', 'crc=0xABCD,c=0xCD이면 인덱스 0, 표[0]=0, 결과 0x00AB입니다. 0xff 마스크가 256개 표 범위를 보장합니다. 이전 높은 바이트는 남고 낮은 바이트는 입력과 함께 전이에 흡수됩니다.'),
     ('CS 연결', '알고리즘의 데이터 의존성을 읽는 연습입니다. 같은 연산 그래프라도 다른 전이 표를 읽으면 다른 함수가 됩니다. extern 선언은 저장소 정의와 다르고 inline은 전체 함수 계약을 바꾸지 않습니다.')],
    [('crc=0xABCD,c=0xCD의 결과는?', '0x00AB', '0xCD00', '낮은 바이트의 XOR가 0이고 표[0]=0이므로 남는 값은 오른쪽으로 이동한 0xAB입니다.'),
     ('crc16_byte와 식이 비슷하면 결과도 항상 같은가?', '아니다. 다른 전이 표를 사용한다', '그렇다. 함수 이름만 다르다', 'crc_ccitt_table과 crc16_table은 각각 다른 다항식으로 만들어졌습니다. 코드 구조의 유사성만으로 데이터 의미까지 같다고 판단하면 안 됩니다.')])

add('lib/crc-itu-t.c', 'CRC ITU-T 전체 구현: 상위 비트부터 진행하는 0x1021',
    '같은 다항식 계열의 반사 구현과 정방향 구현을 비교해 비트 방향을 이해합니다.',
    'crc_itu_t_table은 0x1021 다항식의 MSB 우선 256개 전이입니다. crc_itu_t는 버퍼를 순회하며 헤더 helper로 상태를 갱신합니다. helper는 crc의 상위 바이트와 입력을 XOR해 표를 선택하고 crc<<8과 결합합니다.',
    '호출자가 초기 상태를 지정하고 반환값을 다음 조각에 이어 쓸 수 있습니다. 마지막 보수·바이트 직렬화는 이 함수가 하지 않습니다. 다른 CRC-CCITT 변형과 비교할 때 입력 방향과 초기값까지 맞추세요.',
    [('전체 파일 범위', 'SPDX·설명, types/module/crc-itu-t 헤더, 0x1021 다항식 주석, 256개 u16 표와 export, crc_itu_t 버퍼 루프와 export, 모듈 정보가 전체입니다. 표는 읽기 전용이며 별도의 초기화 함수는 없습니다.'),
     ('독립적인 표 재구성', '인덱스 i를 i<<8로 놓고 8회 상위 비트를 확인합니다. r=((r<<1) XOR (이전 0x8000 비트가 있으면 0x1021)) & 0xffff로 갱신하면 표[i]가 됩니다. 이 비트 루프는 표를 복사하지 않고 전체 256개 값을 검산하는 방법입니다.'),
     ('입력 추적과 경계', '초기 0, 입력 1은 tab[1]=0x1021입니다. 다음 입력 0x10이면 상위 바이트와 상쇄되어 표[0]=0, 이전 상태를 왼쪽으로 이동한 하위 16비트 0x2100이 됩니다. len=0은 초기 상태 그대로이며 데이터는 수정하지 않습니다.'),
     ('CS 연결', '256개 u16 전이는 512바이트의 시간·공간 절충이며 n바이트 순회는 O(n)입니다. '+COMMON)],
    [('초기 0에서 [1,0x10]의 결과는?', '0x2100', '0x0010', '첫 상태는 0x1021입니다. 다음 입력 0x10과 상위 바이트가 상쇄되어 표[0]=0이고 (0x1021<<8)의 하위 16비트인 0x2100이 남습니다.'),
     ('CCITT 반사 구현과 이 구현은 0x1021 계열이라는 이유로 같은 입력에 늘 같은 값을 내는가?', '아니다. 비트 처리 방향과 표현 등이 다르다', '그렇다. 다항식만 같으면 나머지 설정은 무관하다', '반사 여부, 초기값, 최종 XOR, 표현을 모두 맞춰야 알고리즘 파라미터가 같습니다. 수학적 다항식 계열만으로 API 결과를 동일시할 수 없습니다.'),
     ('이 함수가 반환값의 전송 바이트 순서까지 정하는가?', '아니다. u16 상태만 반환한다', '그렇다. 네트워크 버퍼에 두 바이트를 자동 기록한다', '입력 buffer는 const이고 함수 안에 출력 버퍼 쓰기가 없습니다. 호출자가 규격에 맞는 순서로 반환값을 직렬화해야 합니다.')])

add('include/linux/crc-itu-t.h', 'CRC ITU-T 헤더 전체: 상위 바이트 선택과 16비트 절단',
    '정수 승격을 거치는 갱신식에서 최종 반환형이 어떤 비트를 남기는지 계산합니다.',
    'crc_itu_t_byte는 (crc<<8) XOR crc_itu_t_table[((crc>>8) XOR data)&0xff]를 반환합니다. 높은 바이트가 새 입력과 섞여 전이를 고르고 낮은 바이트는 한 바이트 왼쪽으로 이동합니다.',
    '버퍼 함수는 외부 선언이고 표도 외부 const 객체입니다. helper의 반환형 u16이 마지막 값을 16비트로 제한합니다. CPU의 저장 바이트 순서가 수식 방향을 바꾸지는 않습니다.',
    [('전체 파일 구성', 'SPDX, 폭 16·다항식 0x1021·기본 Init 0 설명, CRC_ITU_T_H 가드, types.h, 외부 표·버퍼 함수 선언, static inline helper 정의, 닫는 가드로 구성됩니다. Init 0 설명은 인자로 다른 누적 상태를 넘기지 못한다는 뜻이 아닙니다.'),
     ('수치 예제와 정수 승격', 'crc=0x1234,data=0x12이면 인덱스는 0이고 표 값도 0입니다. crc<<8은 승격된 정수에서 0x123400이 될 수 있으며 u16 반환 변환으로 0x3400이 남습니다. Linux의 통상 32비트 int에서 16비트 최대값의 8비트 이동은 int 범위 안입니다.'),
     ('CS 연결', '인덱스 폭의 마스크와 반환값 폭의 절단은 서로 다른 위치의 작업입니다. 식을 손으로 계산할 때 중간값·표 인덱스·최종 반환값을 분리하면 엔디언·정수 승격·비트 방향 혼동을 줄일 수 있습니다.')],
    [('crc=0x1234,data=0x12의 최종 u16 반환값은?', '0x3400', '0x123400', '상위 바이트와 data가 상쇄되어 표[0]=0입니다. 왼쪽 이동의 중간값 0x123400은 반환형 u16으로 변환되며 하위 16비트 0x3400만 남습니다.'),
     ('이 helper의 표 인덱스에 쓰는 이전 상태 부분은?', '상위 8비트', '하위 8비트', 'crc>>8로 높은 바이트를 먼저 꺼냅니다. crc_ccitt_byte의 (crc XOR data)&0xff처럼 낮은 바이트를 사용하는 식과 다릅니다.')])
